package com.johnny.hotel.cleaning;import com.johnny.hotel.common.Result;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/housekeeping") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')") public class HousekeepingController {private final CleaningService service;private Long id(Authentication a){return(Long)a.getDetails();}@PostMapping("/bookings/{bookingId}/cleaning-requests")public Result<StayoverCleaningRequest> request(@PathVariable Long bookingId,@Valid @RequestBody CleaningRequests.Create r,Authentication a){return Result.success(service.requestStayover(bookingId,r,id(a),false));}@PostMapping("/tasks/{taskId}/complete")public Result<CleaningRecord> complete(@PathVariable Long taskId,@Valid @RequestBody(required=false) CleaningRequests.Complete r){return Result.success(service.complete(taskId,r==null?null:r.getNotes(),r!=null&&Boolean.TRUE.equals(r.getForce())));}@PostMapping("/tasks/{taskId}/cancel")public Result<Void> cancel(@PathVariable Long taskId,@Valid @RequestBody(required=false) CleaningRequests.Cancel r){service.cancel(taskId,r==null?null:r.getNotes());return Result.success(null);}@GetMapping("/rooms/{roomId}/cleaning-records")public Result<List<CleaningRecord>> room(@PathVariable Long roomId){return Result.success(service.roomHistory(roomId));}@GetMapping("/bookings/{bookingId}/cleaning-records")public Result<List<CleaningRecord>> booking(@PathVariable Long bookingId){return Result.success(service.bookingHistory(bookingId));}@GetMapping("/assignments/{assignmentId}/cleaning-records")public Result<List<CleaningRecord>> assignment(@PathVariable Long assignmentId){return Result.success(service.assignmentHistory(assignmentId));}@GetMapping("/cleaning-records/{id}")public Result<CleaningRecord> get(@PathVariable Long id){return Result.success(service.get(id));}}
